Or if you just want a pattern example, common options:

**React with useState + useEffect:**
```jsx
const [search, setSearch] = useState('');

useEffect(() => {
  const timer = setTimeout(() => {
    if (search) fetchResults(search);
  }, 300);
  return () => clearTimeout(timer);
}, [search]);

return <input value={search} onChange={e => setSearch(e.target.value)} />;
```

**React with useRef (manual debounce):**
```jsx
const timerRef = useRef(null);

const handleSearch = (query) => {
  clearTimeout(timerRef.current);
  timerRef.current = setTimeout(() => fetchResults(query), 300);
};

return <input onChange={e => handleSearch(e.target.value)} />;
```

**Vanilla JS:**
```js
let timer;
input.addEventListener('input', (e) => {
  clearTimeout(timer);
  timer = setTimeout(() => fetchResults(e.target.value), 300);
});
```

